import{_ as e,o as l,c as i,ag as t}from"./chunks/framework.-Wrcbzkw.js";const u=JSON.parse('{"title":"D2C 测试验证 Agent 设计","description":"","frontmatter":{},"headers":[],"relativePath":"project/D2C/测试验证Agent设计.md","filePath":"project/D2C/测试验证Agent设计.md","lastUpdated":1781078576000}'),r={name:"project/D2C/测试验证Agent设计.md"};function n(o,a,h,d,p,s){return l(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="d2c-测试验证-agent-设计" tabindex="-1">D2C 测试验证 Agent 设计 <a class="header-anchor" href="#d2c-测试验证-agent-设计" aria-label="Permalink to &quot;D2C 测试验证 Agent 设计&quot;">​</a></h1><p>测试验证 Agent 是 D2C 流水线的最后一个阶段。它负责检查代码生成 Agent 的输出，发现语法、依赖、安全、组件 API 和视觉还原问题，并在条件允许时自动修复。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>生成代码 -&gt; 测试验证 Agent -&gt; 检查报告 / 修复后的代码</span></span></code></pre></div><h2 id="一、为什么生成代码后还需要验证" tabindex="-1">一、为什么生成代码后还需要验证 <a class="header-anchor" href="#一、为什么生成代码后还需要验证" aria-label="Permalink to &quot;一、为什么生成代码后还需要验证&quot;">​</a></h2><p>大模型生成的是概率结果。即使输入结构和知识资料都正确，也可能出现：</p><ul><li>标签、括号或字符串没有闭合</li><li>忘记导入组件或依赖</li><li>使用不存在的组件属性</li><li>TypeScript 类型错误</li><li>列表缺少 <code>key</code></li><li>生成存在 XSS 风险的代码</li><li>页面能够编译，但视觉结构与设计稿不一致</li></ul><p>如果没有验证阶段，错误会直接交给开发者，D2C 只能完成“生成”，无法保证“可用”。</p><h2 id="二、测试验证-agent-的设计目标" tabindex="-1">二、测试验证 Agent 的设计目标 <a class="header-anchor" href="#二、测试验证-agent-的设计目标" aria-label="Permalink to &quot;二、测试验证 Agent 的设计目标&quot;">​</a></h2><ol><li>检查代码是否能够解析和编译</li><li>验证导入、组件 API 和依赖是否正确</li><li>检查常见安全与代码质量问题</li><li>比较生成结构与 DSL 是否一致</li><li>输出清晰的错误报告</li><li>对低风险问题进行自动修复</li></ol><h2 id="三、为什么需要规则检查与大模型审查结合" tabindex="-1">三、为什么需要规则检查与大模型审查结合 <a class="header-anchor" href="#三、为什么需要规则检查与大模型审查结合" aria-label="Permalink to &quot;三、为什么需要规则检查与大模型审查结合&quot;">​</a></h2><p>确定性问题适合使用编译器、AST 和静态规则检查：</p><ul><li>标签和括号匹配</li><li>未定义变量</li><li>缺失导入</li><li>TypeScript 类型错误</li><li>危险 API 使用</li></ul><p>开放性问题更适合大模型辅助判断：</p><ul><li>组件划分是否合理</li><li>代码是否可维护</li><li>是否正确理解业务语义</li><li>修复方案如何最小化影响</li></ul><p>使用静态检查作为第一道防线，再让大模型处理复杂问题，比完全依赖模型自检更可靠。</p><h2 id="四、为什么不能让代码生成-agent-自己保证正确" tabindex="-1">四、为什么不能让代码生成 Agent 自己保证正确 <a class="header-anchor" href="#四、为什么不能让代码生成-agent-自己保证正确" aria-label="Permalink to &quot;四、为什么不能让代码生成 Agent 自己保证正确&quot;">​</a></h2><p>让同一个模型在一次生成中同时写代码并自我验证，容易忽略自身错误。独立验证阶段可以使用不同上下文、不同规则，甚至不同模型进行检查。</p><p>职责拆分还带来以下好处：</p><ul><li>可以重复验证而不重新生成</li><li>可以记录错误类型和发生频率</li><li>可以衡量不同代码生成模型的质量</li><li>可以将失败反馈回具体阶段</li><li>可以逐步建立自动修复闭环</li></ul><h2 id="五、建议的验证层次" tabindex="-1">五、建议的验证层次 <a class="header-anchor" href="#五、建议的验证层次" aria-label="Permalink to &quot;五、建议的验证层次&quot;">​</a></h2><h3 id="_1-语法与-ast-检查" tabindex="-1">1. 语法与 AST 检查 <a class="header-anchor" href="#_1-语法与-ast-检查" aria-label="Permalink to &quot;1. 语法与 AST 检查&quot;">​</a></h3><p>确认代码可以被解析，标签、括号和语法结构完整。</p><h3 id="_2-编译与类型检查" tabindex="-1">2. 编译与类型检查 <a class="header-anchor" href="#_2-编译与类型检查" aria-label="Permalink to &quot;2. 编译与类型检查&quot;">​</a></h3><p>运行目标项目的构建、TypeScript 和 Lint 命令。</p><h3 id="_3-组件与依赖检查" tabindex="-1">3. 组件与依赖检查 <a class="header-anchor" href="#_3-组件与依赖检查" aria-label="Permalink to &quot;3. 组件与依赖检查&quot;">​</a></h3><p>确认组件真实存在、导入路径正确、属性符合检索到的文档。</p><h3 id="_4-安全检查" tabindex="-1">4. 安全检查 <a class="header-anchor" href="#_4-安全检查" aria-label="Permalink to &quot;4. 安全检查&quot;">​</a></h3><p>检查 XSS、危险 HTML 注入、硬编码密钥和不安全依赖使用。</p><h3 id="_5-视觉验证" tabindex="-1">5. 视觉验证 <a class="header-anchor" href="#_5-视觉验证" aria-label="Permalink to &quot;5. 视觉验证&quot;">​</a></h3><p>运行生成页面并与设计稿截图比较，检查布局、颜色、间距和字体差异。</p><h2 id="六、自动修复的边界" tabindex="-1">六、自动修复的边界 <a class="header-anchor" href="#六、自动修复的边界" aria-label="Permalink to &quot;六、自动修复的边界&quot;">​</a></h2><p>适合自动修复的问题包括：</p><ul><li>补全缺失导入</li><li>修复简单语法错误</li><li>添加列表 <code>key</code></li><li>替换明确错误的组件属性</li></ul><p>涉及业务逻辑、权限、安全或大规模结构变化时，应输出报告并交给开发者确认，避免自动修复引入更严重问题。</p><h2 id="七、如何评估验证-agent" tabindex="-1">七、如何评估验证 Agent <a class="header-anchor" href="#七、如何评估验证-agent" aria-label="Permalink to &quot;七、如何评估验证 Agent&quot;">​</a></h2><p>可以关注以下指标：</p><ul><li>首次生成代码的编译通过率</li><li>验证后代码的编译通过率</li><li>错误检出率与误报率</li><li>自动修复成功率</li><li>视觉相似度</li><li>人工接管和修改次数</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>测试验证 Agent 为 D2C 建立了生成后的质量闭环。它将“看起来像代码”的模型输出，逐步验证为能够编译、符合规范并尽量还原设计稿的可用代码。</p>',39)])])}const _=e(r,[["render",n]]);export{u as __pageData,_ as default};
